9	/**
10	 * Adds a specified number of days to a given date.
11	 *
12	 * @param date - The base date to add days to
13	 * @param days - The number of days to add (can be negative to subtract days)
14	 * @returns A new Date object with the specified number of days added
15	 *
16	 * @example
17	 * ```ts
18	 * const today = new Date('2024-01-01');
19	 * const nextWeek = addDays(today, 7); // 2024-01-08
20	 * const lastWeek = addDays(today, -7); // 2023-12-25
21	 * ```
22	 */
23	const addDays = (date: Date, days: number) => {
24	    const next = new Date(date);
25	    next.setDate(next.getDate() + days);
26	    return next;
27	};
28	
29	/**
30	 * Normalizes a date to 6:00 PM (18:00) on the same day.
31	 *
32	 * @param date - The date to normalize
33	 * @returns A new Date object set to 18:00:00.000 on the same day as the input date
34	 */
35	const normalizeGameDayTime = (date: Date) => {
36	    return new Date(
37	        date.getFullYear(),
38	        date.getMonth(),
39	        date.getDate(),
40	        18,
41	        0,
42	        0,
43	        0,
44	    );
45	};
46	
47	/**
48	 * Calculates the booking year end date based on the given date. The booking
49	 * year runs from August 1st to July 31st. If the date is in August or later
50	 * (month >= 7), returns July 31st of the following year at 18:00:00. Otherwise,
51	 * returns July 31st of the current year at 18:00:00.
52	 *
53	 * @param date - The date to calculate the booking year end from
54	 * @returns A Date object representing the end of the booking year (July 31st at
55	 * 18:00:00)
56	 */
57	const getBookingYearEnd = (date: Date) => {
58	    const year = date.getFullYear();
59	    const isAfterJuly = date.getMonth() >= 7;
60	    const endYear = isAfterJuly ? year + 1 : year;
61	    return new Date(endYear, 6, 31, 18, 0, 0, 0);
62	};
63	
64	/**
65	 * Calculates the date of the next Tuesday from a given date. If the given date
66	 * is a Tuesday, returns the following Tuesday (7 days later).
67	 *
68	 * @param from - The reference date to calculate from
69	 * @returns A Date object representing the next Tuesday after the given date
70	 *
71	 * @example
72	 * ```ts
73	 * const nextTuesday = getNextTuesday(new Date('2024-01-15')); // Returns Tuesday, Jan 16
74	 * const fromTuesday = getNextTuesday(new Date('2024-01-16')); // Returns Tuesday, Jan 23
75	 * ```
76	 */
77	const getNextTuesday = (from: Date) => {
78	    const day = from.getDay();
79	    const daysUntilTuesday = (2 - day + 7) % 7;
80	    const candidate = addDays(from, daysUntilTuesday);
81	    return candidate <= from ? addDays(candidate, 7) : candidate;
82	};
83	
84	/**
85	 * Builds an array of weekly game rows from a start date to the end of the
86	 * booking year.
87	 *
88	 * Each row represents a game scheduled 7 days apart, starting from the given
89	 * date and continuing until the booking year end date (inclusive).
90	 *
91	 * @param startDate - The date to begin scheduling games from
92	 * @returns An array of game row objects, each containing:
93	 *   - `date`: ISO format date string (YYYY-MM-DD)
94	 *   - `game`: Boolean flag set to true indicating a game is scheduled
95	 *   - `comment`: Empty string for additional notes
96	 */
97	const buildRows = (startDate: Date) => {
98	    const endDate = getBookingYearEnd(startDate);
99	    const rows = [];
100	
101	    for (
102	        let date = new Date(startDate);
103	        date <= endDate;
104	        date = addDays(date, 7)
105	    ) {
106	        rows.push({
107	            date: formatDate(date),
108	            game: true,
109	            comment: '',
110	        });
111	    }
112	
113	    return rows;
114	};
