11	/**
12	 * Server component that enforces admin authentication for the admin section.
13	 *
14	 * This layout checks the current user's role using `getUserRole()`. If the user is not an admin,
15	 * it redirects them to the admin sign-in page, preserving the current pathname for post-login redirection.
16	 * If the user is an admin, it renders the provided children components.
17	 *
18	 * @param {AdminLayoutProps} props - The props object containing the `children` to render.
19	 * @returns The rendered children if the user is an admin, otherwise triggers a redirect.
20	 */
21	export default async function AdminLayout({ children }: AdminLayoutProps) {
22	    const role = await getUserRole();
23	
24	    if (role !== 'admin') {
25	        const headersList = await headers();
26	        const pathname = headersList.get('x-pathname') ?? '/footy/admin';
27	        redirect(
28	            `/footy/auth/signin?admin=true&redirect=${encodeURIComponent(pathname)}`,
29	        );
30	    }
31	
32	    return children;
33	}
