15	interface PageProps {
16	    params: Promise<{ id: string }>;
17	}
18	
19	/**
20	 * Unpacks and validates route parameters for the game detail page.
21	 *
22	 * Validates the `id` parameter as a positive integer, retrieves the
23	 * corresponding game day, and handles redirects to the canonical URL if needed.
24	 *
25	 * @param params - The route parameters object containing the `id` property
26	 * @returns A promise that resolves to an object containing the validated
27	 * `gameDay`
28	 * @throws Calls `notFound()` if the game day cannot be found or the ID is
29	 * invalid
30	 * @throws Calls `permanentRedirect()` if the current URL doesn't match the
31	 * canonical URL
32	 */
33	const unpackParams = cache(async (params: PageProps['params']) => {
34	    const { id } = await params;
35	
36	    const gameDayId = z.coerce.number().int().min(1).safeParse(id);
37	    const gameDay = gameDayId.success
38	        ? await gameDayService.get(gameDayId.data)
39	        : undefined;
40	    if (!gameDay) notFound();
41	
42	    const canonicalUrl = `/footy/game/${gameDay.id}`;
43	    const currentUrl = `/footy/game/${id}`;
44	    if (currentUrl !== canonicalUrl) permanentRedirect(canonicalUrl);
45	
46	    return { gameDay };
47	});
48	
49	/**
50	 * Generates metadata for a game page.
51	 * @param props - The page props containing route parameters
52	 * @param props.params - Route parameters including the game ID
53	 * @returns A promise that resolves to metadata with the game title and date
54	 */
55	export async function generateMetadata(props: PageProps): Promise<Metadata> {
56	    const { gameDay } = await unpackParams(props.params);
57	
58	    return {
59	        title: formatDate(gameDay.date),
60	    };
61	}
