63	/**
64	 * Displays a football game day page with game details, team information, and
65	 * navigation.
66	 *
67	 * This is an async Server Component that fetches game data, determines user
68	 * role, and renders game results, player teams, and administrative controls
69	 * based on permissions.
70	 *
71	 * @component
72	 * @param {PageProps} props - The page component props
73	 * @param {object} props.params - Route parameters containing the game ID
74	 * @returns {Promise<React.ReactElement>} Game navigation, admin controls, and
75	 * game summary, rendered by GameDaySummary
76	 *
77	 * @remarks
78	 * - Fetches previous and next game days for navigation
79	 * - Retrieves team rosters (up to 10 players per team) for the current game day
80	 * - Passes `isAdmin` through to GameDaySummary, which only displays the
81	 *   GameResultForm if the user has an 'admin' role
82	 * - Navigation links (Previous/Next) are conditionally rendered based on data
83	 *   availability
84	 *
85	 * @requires getUserRole - To determine user permissions
86	 * @requires unpackParams - To extract gameDay from route params
87	 * @requires gameDayService.getPrevious - To fetch previous game
88	 * @requires gameDayService.getNext - To fetch next game
89	 * @requires outcomeService.getTeamPlayersByGameDay - To fetch team rosters
90	 */
91	const GamePage = async (props: PageProps) => {
92	    const { gameDay } = await unpackParams(props.params);
93	    const [role, prevGameDay, nextGameDay, teamA, teamB] = await Promise.all([
94	        getUserRole(),
95	        gameDayService.getPrevious(gameDay.id),
96	        gameDayService.getNext(gameDay.id),
97	        outcomeService.getTeamPlayersByGameDay(gameDay.id, 'A', 10),
98	        outcomeService.getTeamPlayersByGameDay(gameDay.id, 'B', 10),
99	    ]);
100	
101	    return (
102	        <>
103	            <AutoRefresh
104	                channels={[FootyChannel.Games, FootyChannel.Results]}
105	            />
106	            <GameDaySummary
107	                gameDay={gameDay}
108	                prevGameDay={prevGameDay}
109	                nextGameDay={nextGameDay}
110	                teamA={teamA}
111	                teamB={teamB}
112	                isAdmin={role === 'admin'}
113	                setGameResult={setGameResult}
114	            />
115	        </>
116	    );
117	};
118	
119	export default GamePage;
