52	/**
53	 * Creates a new player using the provided input data and dependencies.
54	 *
55	 * This function trims and validates the input fields, converts the introducer
56	 * to a number if present, and normalizes the email address. It then creates a
57	 * player record via the injected player service, and generates an invite link
58	 * for the newly created player.
59	 *
60	 * @param data - The input data required to create a player.
61	 * @param deps - Optional dependencies for player creation. Defaults to
62	 * `defaultDeps`.
63	 * @returns An object containing the created player and an invite link.
64	 * @throws {ValidationError} If the introducer is provided but is not a valid
65	 * number.
66	 */
67	export async function createPlayerCore(
68	    data: CreatePlayerInput,
69	    deps: CreatePlayerDeps = defaultDeps,
70	) {
71	    const name = data.name.trim();
72	    const introducedBy = data.introducedBy.trim();
73	    const introducedById = introducedBy ? Number(introducedBy) : null;
74	    const accountEmail = data.email?.trim()
75	        ? data.email.trim().toLowerCase()
76	        : null;
77	
78	    if (introducedBy && Number.isNaN(introducedById)) {
79	        throw new ValidationError('Introducer must be a number.');
80	    }
81	
82	    const player = await deps.playerService.create({
83	        name,
84	        introducedBy: introducedById,
85	        joined: new Date(),
86	        accountEmail,
87	    });
88	
89	    return {
90	        player,
91	        inviteLink: await addPlayerInviteCore(player.id, data.email, deps),
92	    };
93	}
