5	function buildSafeRel(
6	    target: string | undefined,
7	    rel: string | undefined,
8	): string | undefined {
9	    if (target?.toLowerCase() !== '_blank') return rel;
10	    const required = ['noopener', 'noreferrer'];
11	    const existing = (rel?.split(/\s+/) ?? [])
12	        .filter(Boolean)
13	        .filter((t) => !required.includes(t.toLowerCase()));
14	    return [...required, ...existing].join(' ');
15	}
