// Scratch-only stand-in for src/lib/auth.ts, built solely so the Better Auth
// CLI's schema generator can load a config without pulling in `server-only`
// (via @/lib/secrets and prisma/prisma). Mirrors only the parts of the real
// config that affect the generated DB schema: additionalFields, plugins,
// account linking, and which social providers are configured. Not used by
// the app - exists only for this one-off `auth generate` sanity check.
import { betterAuth } from 'better-auth';
import { prismaAdapter } from 'better-auth/adapters/prisma';
import { nextCookies } from 'better-auth/next-js';
import { admin } from 'better-auth/plugins';

export const auth = betterAuth({
    database: prismaAdapter({} as never, { provider: 'mysql' }),
    user: {
        additionalFields: {
            playerId: {
                type: 'number',
                required: false,
            },
        },
    },
    emailAndPassword: { enabled: true },
    account: {
        accountLinking: {
            enabled: true,
            trustedProviders: ['google', 'microsoft'],
        },
    },
    plugins: [admin(), nextCookies()],
    socialProviders: {
        google: { clientId: 'dummy', clientSecret: 'dummy' },
        microsoft: {
            clientId: 'dummy',
            clientSecret: 'dummy',
            tenantId: 'dummy',
        },
    },
});

