// Scratch-only stand-in for src/lib/auth.ts, built solely so the Better Auth
// CLI's create-admin command can load a config without pulling in
// `server-only` (via @/lib/secrets and prisma/prisma). Connects to the real
// dev database directly via DATABASE_URL, bypassing the app's prisma.ts
// singleton (which itself imports server-only). Not used by the app -
// deleted immediately after this one-off bootstrap.
import { PrismaMariaDb } from '@prisma/adapter-mariadb';
import { betterAuth } from 'better-auth';
import { prismaAdapter } from 'better-auth/adapters/prisma';
import { admin } from 'better-auth/plugins';
import { PrismaClient } from 'prisma/generated/client';

const adapter = new PrismaMariaDb(process.env.DATABASE_URL!);
const prisma = new PrismaClient({ adapter });

export const auth = betterAuth({
    database: prismaAdapter(prisma, { provider: 'mysql' }),
    user: {
        additionalFields: {
            playerId: {
                type: 'number',
                required: false,
            },
        },
    },
    emailAndPassword: { enabled: true },
    plugins: [admin()],
});
